class Solution {
  char[] s;
  int[] pre, suf, best;
  char[] left, right;

  public int[] longestRepeating(String str, String queryCharacters, int[] queryIndices) {
    s = str.toCharArray();
    int n = s.length;
    pre = new int[4 * n];
    suf = new int[4 * n];
    best = new int[4 * n];
    left = new char[4 * n];
    right = new char[4 * n];
    build(1, 0, n - 1);
    int[] ans = new int[queryIndices.length];
    for (int i = 0; i < ans.length; i++) {
      s[queryIndices[i]] = queryCharacters.charAt(i);
      update(1, 0, n - 1, queryIndices[i]);
      ans[i] = best[1];
    }
    return ans;
  }

  void build(int p, int l, int r) {
    if (l == r) {
      pre[p] = suf[p] = best[p] = 1;
      left[p] = right[p] = s[l];
      return;
    }
    int m = (l + r) / 2;
    build(p * 2, l, m);
    build(p * 2 + 1, m + 1, r);
    pull(p, l, r, m);
  }

  void update(int p, int l, int r, int i) {
    if (l == r) {
      pre[p] = suf[p] = best[p] = 1;
      left[p] = right[p] = s[l];
      return;
    }
    int m = (l + r) / 2;
    if (i <= m) update(p * 2, l, m, i);
    else update(p * 2 + 1, m + 1, r, i);
    pull(p, l, r, m);
  }

  void pull(int p, int l, int r, int m) {
    int a = p * 2, b = a + 1;
    left[p] = left[a];
    right[p] = right[b];
    pre[p] = pre[a];
    suf[p] = suf[b];
    best[p] = Math.max(best[a], best[b]);
    if (right[a] == left[b]) {
      best[p] = Math.max(best[p], suf[a] + pre[b]);
      if (pre[a] == m - l + 1) pre[p] += pre[b];
      if (suf[b] == r - m) suf[p] += suf[a];
    }
  }
}
